-- Read-back after block 5a (+ 5b). Run: node scripts/verification/prod-query.mjs scripts/verification/apply/readback-fll-gar-coverage-block5.sql
-- Expected after 5a: 25 fields; the five select_one fields carry enum_values generated from TAB19 (14) / TAB21 (47) / TAB23 (3) / TAB14 (2) / TAB9 (3) / TAB10 (3).
select w.code ws, f.symbol, f.widget, jsonb_array_length(coalesce(f.enum_values, '[]'::jsonb)) n_options, f.lookup->>'table_code' fill_table, f.is_required
  from fields f join worksheet_templates w on w.id = f.worksheet_template_id join standards s on s.id = w.standard_id
 where s.code = 'FLL-GAR-2023' and f.symbol in ('bb_kurzzeichen_tab19', 'bb_bahnenart_tab19', 'bahn_bezeichnung_tab21', 'bahn_stoffgruppe_tab21', 'bahn_bahnenart_tab21', 'fk_stoff_tab23', 'fk_schichtdicke_min_mm', 'fk_eta_mindestschichtdicke_mm', 'fk_einlage_min_g_m2', 'fk_einlage_g_m2', 'gtd_geotextil_art_tab14', 'gtd_geotextil_flaecheneinheit_min', 'gtd_geotextil_flaecheneinheit_g_m2', 'gtd_zugfestigkeit_kn_m', 'gtd_zugfestigkeitsdehnung_pct', 'gtd_verbundfestigkeit_n_m', 'gtd_kf_m_s', 'gtd_permittivitaet_m_s', 'frischbeton_lufttemperatur_fall', 'frischbeton_temp_min_c', 'frischbeton_temperatur_c', 'zementfestigkeitsklasse_tab10', 'erhaertungszeit_tage_bei_5c', 'erhaertungszeit_tage_bei_12c', 'erhaertungszeit_tage_bei_20c') order by w.code, f.order_index;
-- Expected after 5b: REQ-41/-42/-43 present; pflanzenarten has a tab29_art column; FLL-GAR-24-D2 counts the Tab.-29 flag.
select w.code ws, cr.code, cr.severity, cr.condition from compliance_requirements cr join worksheet_templates w on w.id = cr.worksheet_template_id join standards s on s.id = w.standard_id where s.code = 'FLL-GAR-2023' and cr.code in ('REQ-41','REQ-42','REQ-43') order by cr.code;
select (f.ui_config->'columns')::text like '%tab29_art%' has_tab29_column from fields f join worksheet_templates w on w.id = f.worksheet_template_id join standards s on s.id = w.standard_id where s.code = 'FLL-GAR-2023' and w.code = 'FLL-GAR-24' and f.symbol = 'pflanzenarten';
select e.formula from equations e join worksheet_templates w on w.id = e.worksheet_template_id join standards s on s.id = w.standard_id where s.code = 'FLL-GAR-2023' and e.equation_number = 'FLL-GAR-24-D2';
